                  <span style={{color:'#374151'}}>{d.variable_legible}</span>
                  <span style={{textAlign:'right',fontWeight:500}}>{Number(d.coeficiente).toFixed(3)}</span>
                  <span style={{textAlign:'right',color:d.significativo?'#6366f1':'#9ca3af'}}>{Number(d.p_valor).toFixed(4)}</span>
                  <span style={{textAlign:'right'}}>
                    <span style={{
                      background: d.significativo?'#eef2ff':'#f3f4f6',
                      color: d.significativo?'#4f46e5':'#9ca3af',
                      padding:'1px 6px',borderRadius:4,fontSize:10,fontWeight:600
                    }}>{d.significativo?'Si':'No'}</span>
                  </span>
                </div>
              ))}
            </div>
          </div>

          <div className="right-panel">
            {/* Métricas del modelo */}
            <div className="card">
              <h3 className="card-title">Desempeño del modelo</h3>
              <p className="card-sub">El R² indica qué proporción de la variación en criminalidad explica el modelo.</p>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:16}}>
                {[
                  { label:'R² pseudo',      value: `${(Number(slagMetrica.r2||0)*100).toFixed(1)}%`,   desc:'Variación explicada por el modelo' },
                  { label:'N observaciones', value: slagMetrica.n || 13,                                desc:'Localidades incluidas en el modelo' },
                  { label:'AIC',             value: Number(slagMetrica.aic||0).toFixed(1),              desc:'Criterio de información — menor es mejor' },
                  { label:'Log-likelihood',  value: Number(slagMetrica.log_likelihood||0).toFixed(1),   desc:'Ajuste del modelo — mayor es mejor' },
                ].map(m=>(
                  <div key={m.label} style={{background:'#fafaf8',borderRadius:8,padding:'12px',border:'1px solid #e8e6e1'}}>
                    <p style={{fontSize:10,color:'#6b7280',marginBottom:4}}>{m.label}</p>
                    <p style={{fontSize:20,fontWeight:700,color:'#1a1a1a',fontFamily:'DM Serif Display, serif'}}>{m.value}</p>
                    <p style={{fontSize:10,color:'#9ca3af',marginTop:2}}>{m.desc}</p>
                  </div>
                ))}
              </div>

              {/* Rho */}
              <div style={{background:'#f3f2ef',borderRadius:8,padding:'14px',marginBottom:0}}>
                <p style={{fontSize:12,fontWeight:600,color:'#374151',marginBottom:4}}>
                  Rho (efecto espacial de los vecinos) = {Number(slagRho.coeficiente||0).toFixed(4)}
                </p>
                <p style={{fontSize:12,color:'#6b7280',lineHeight:1.5}}>
                  {Number(slagRho.p_valor||1) < 0.05
                    ? `El efecto de los vecinos es estadísticamente significativo. Las tasas de criminalidad de una localidad están influenciadas por las de sus localidades vecinas.`
                    : `El Rho no es significativo (p = ${Number(slagRho.p_valor||1).toFixed(4)}). Esto indica que, controlando por el perfil de delitos, el efecto de los vecinos no es estadísticamente distinguible de cero. El modelo espacial confirma que son los tipos de delito propios — no el contagio geográfico — los que explican el riesgo.`
                  }
                </p>
              </div>
            </div>

            {/* Predicciones vs reales */}
            <div className="card">
              <h3 className="card-title">Predicciones vs. valores reales</h3>
              <p className="card-sub">Cada fila compara la tasa real de la localidad con lo que predice el modelo. Residuos pequeños indican buen ajuste.</p>
              <div style={{display:'flex',flexDirection:'column',gap:4,maxHeight:280,overflowY:'auto'}}>
                <div style={{display:'grid',gridTemplateColumns:'2fr 1fr 1fr 1fr',gap:4,fontSize:10,fontWeight:600,color:'#6b7280',borderBottom:'1px solid #e8e6e1',paddingBottom:5,marginBottom:4}}>
                  <span>Localidad</span><span style={{textAlign:'right'}}>Real</span><span style={{textAlign:'right'}}>Predicho</span><span style={{textAlign:'right'}}>Residuo</span>
                </div>
                {[...slagPred].sort((a,b)=>b.tasa_real-a.tasa_real).map((d,i)=>(
                  <div key={i} style={{display:'grid',gridTemplateColumns:'2fr 1fr 1fr 1fr',gap:4,fontSize:11,padding:'4px 0',borderBottom:'1px solid #f3f4f6',alignItems:'center'}}>
                    <span style={{color:'#374151',fontSize:10}}>{String(d.localidad||'').charAt(0)+String(d.localidad||'').slice(1).toLowerCase()}</span>
                    <span style={{textAlign:'right',fontWeight:500}}>{Number(d.tasa_real).toFixed(0)}</span>
                    <span style={{textAlign:'right',color:'#6366f1'}}>{Number(d.tasa_predicha).toFixed(0)}</span>
                    <span style={{textAlign:'right',color:Math.abs(Number(d.residuo))>50?'#ef4444':'#10b981',fontSize:10}}>
                      {Number(d.residuo)>0?'+':''}{Number(d.residuo).toFixed(0)}
                    </span>
                  </div>
                ))}
              </div>
              <p className="chart-note">Verde = residuo pequeño (ajuste bueno). Rojo = residuo mayor a 50.</p>
            </div>

            <div className="insight-box">
              <p>
                <strong>¿Por qué este modelo y no Random Forest?</strong> El Spatial Lag Model produce
                coeficientes interpretables directamente — cada número tiene un significado concreto en
                el contexto de la criminalidad. El R² de {(Number(slagMetrica.r2||0)*100).toFixed(1)}% indica
                que el modelo explica prácticamente toda la variación observada con solo 6 variables de delito.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* 06 · VALIDACIÓN */}
      <section id="validation" className="section section-alt">
        <SectionHeader
          eyebrow="06 · Validación"
          title="¿El modelo funciona bien cuando los vecinos no están disponibles?"
          desc="Comparamos Leave-One-Out (clásica) y Spatial Block CV (espacial). La segunda excluye también las vecinas de la localidad de prueba, evitando que el modelo aproveche la autocorrelación espacial."
        />
        <div className="two-col">
          <div className="validation-cards">
            {validacion.map((v,i)=>(
              <div className="val-card" key={i}>
                <span className="val-type">{v.tipo_validacion}</span>
                <p className="val-desc">{v.descripcion}</p>
                <div className="val-metrics">
                  <div className="val-metric">
                    <div className="val-circle" style={{background:`conic-gradient(#6366f1 ${Number(v.accuracy)*360}deg, #e5e7eb 0deg)`}}>
                      <span>{(Number(v.accuracy)*100).toFixed(1)}%</span>
                    </div>
                    <label>Accuracy</label>
                  </div>
                  <div className="val-metric">
                    <div className="val-circle" style={{background:`conic-gradient(#8b5cf6 ${Number(v.f1_weighted)*360}deg, #e5e7eb 0deg)`}}>
                      <span>{(Number(v.f1_weighted)*100).toFixed(1)}%</span>
                    </div>
                    <label>F1-score</label>
                  </div>
                </div>
                <p className="val-interp">{v.interpretacion}</p>
              </div>
            ))}
          </div>
          <div className="right-panel">
            <div className="card">
              <h3 className="card-title">Comparación visual de métricas</h3>
              <p className="card-sub">La diferencia revela cuánto depende el modelo de la autocorrelación espacial.</p>
              <div className="diff-viz">
                {validacion.map((v,i)=>(
                  <div className="diff-bar-container" key={i}>
                    <div className="diff-label">{v.tipo_validacion}</div>
                    <div className="diff-bar-track">
                      <div className="diff-bar-fill" style={{width:`${Number(v.accuracy)*100}%`,background:i===0?'#6366f1':'#8b5cf6'}}/>
                      <span className="diff-bar-val">{(Number(v.accuracy)*100).toFixed(1)}%</span>
                    </div>
                  </div>
                ))}
                {validacion.length===2&&(
                  <div className="diff-conclusion">
                    <span className="diff-delta">
                      Diferencia = {Math.abs((Number(validacion[0].accuracy)-Number(validacion[1].accuracy))*100).toFixed(1)} pp
                    </span>
                    <p>Una diferencia pequeña indica que el modelo generaliza bien incluso sin la información de los vecinos geográficos.</p>
                  </div>
                )}
              </div>
            </div>
            <div className="explain-cards">
              <div className="explain-item">
                <span className="explain-tag" style={{background:'#6366f1'}}>LOO</span>
                <div><strong>Leave-One-Out</strong><p>Cada localidad se prueba con las 18 restantes. Puede ser optimista si las vecinas están en el set de entrenamiento.</p></div>
              </div>
              <div className="explain-item">
                <span className="explain-tag" style={{background:'#8b5cf6'}}>SCV</span>
                <div><strong>Spatial Block CV</strong><p>Al evaluar la localidad i, también se excluyen sus vecinas directas. La métrica más honesta para datos autocorrelacionados.</p></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* 07 · CONCLUSIONES */}
      <section id="interpretation" className="section">
        <SectionHeader
          eyebrow="07 · Conclusiones"
          title="¿Qué nos dice el análisis sobre la criminalidad en Bogotá?"
          desc="Los modelos no hablan solos. Traducimos los resultados técnicos en conclusiones sobre la dinámica urbana del delito en la capital colombiana."
        />
        <div className="interpretation-grid">
          <InterpCard
            title="Epicentro claro en el centro histórico"
            body="Los Mártires (5.872), La Candelaria (5.166) y Santa Fe (4.117) son zonas críticas según LISA (Santa Fe = HH) y K-Means (Cluster Alto). Alto flujo peatonal, comercio informal y nocturnidad generan las condiciones para el hurto."
          />
          <InterpCard
            title="La periferia sur tiene un riesgo diferente"
            body="Ciudad Bolívar, Usme y Bosa tienen las tasas totales más bajas, pero su violencia intrafamiliar y homicidios son proporcionalmente más altos. El riesgo doméstico requiere respuestas de política social, no solo policial."
          />
          <InterpCard
            title="Los delitos no son aleatorios"
            body="Todos los delitos presentan I de Moran positivo y significativo (999 permutaciones). El hurto a personas (I=0.469) tiene el clustering más fuerte. Las intervenciones focalizadas tienen sustento estadístico robusto."
          />
          <InterpCard
            title="El hurto y el comercio explican el riesgo"
            body="El Spatial Lag Model confirma que el hurto a personas (coef. 0.95, p=0.00) y el hurto a comercio (coef. 1.77, p=0.00) son los predictores más significativos de la tasa total. Los homicidios no son significativos, lo que cuestiona políticas centradas solo en ese indicador."
          />
          <InterpCard
            title="El riesgo es propio, no contagiado"
            body="El Rho del modelo espacial no es significativo (p=0.277), lo que indica que controlando por el perfil de delitos propios, el efecto de los vecinos desaparece. El riesgo de cada localidad se explica por su dinámica interna, no por contagio geográfico."
          />
          <InterpCard
            title="Limitaciones que importan"
            body="El modelo cubre 13 de 19 localidades por limitaciones del merge geoespacial. Con 19 localidades los modelos son ilustrativos. Un análisis a nivel UPZ o barrio daría mayor resolución estadística y permitiría conclusiones más robustas."
          />
        </div>
      </section>

      {/* FOOTER */}
      <footer className="footer">
        <p>Análisis Espacial de Criminalidad Urbana · Bogotá D.C. · 2021–2024</p>
        <p className="footer-sub">Datos: SIEDCO (Policía Nacional) · Cartografía: Datos Abiertos Bogotá · Análisis: Python · pysal · spreg · scikit-learn</p>
        <p className="footer-sub">Proyecto académico · Series Temporales y Datos Geoespaciales</p>
      </footer>
    </div>
  );
}

function SectionHeader({ eyebrow, title, desc }) {
  return (
    <div className="section-header">
      <p className="eyebrow">{eyebrow}</p>
      <h2>{title}</h2>
      <p className="section-desc">{desc}</p>
    </div>
  );
}

function InterpCard({ title, body }) {
  return (
    <div className="interp-card">
      <h4>{title}</h4>
      <p>{body}</p>
    </div>
  );
}
